import org.springframework.expression.Expression;
import org.springframework.expression.ExpressionParser;
import org.springframework.expression.spel.standard.SpelExpressionParser;
import org.springframework.expression.spel.support.StandardEvaluationContext;
import org.springframework.web.bind.annotation.*;

@RestController
public class TaxRuleController {
    private final ExpressionParser parser = new SpelExpressionParser();
    // 硬编码的税率表达式，编译期固定，不含用户输入
    private final Expression taxExpr = parser.parseExpression(
            "#order.amount * #rate - #order.discount");

    @PostMapping("/api/tax/calc")
    public Object calcTax(@RequestBody Order order) {
        StandardEvaluationContext ctx = new StandardEvaluationContext();
        ctx.setVariable("order", order);
        ctx.setVariable("rate", 0.13);
        return taxExpr.getValue(ctx);
    }
}

