@RestController
@RequestMapping("/api/internal")
public class InternalApiController {
    @GetMapping("/sync")
    public SyncResult sync(HttpServletRequest req) {
        // mTLS：从请求提取客户端证书，校验 CN 是否为受信任服务
        X509Certificate[] certs = (X509Certificate[]) req.getAttribute(
                "javax.servlet.request.X509Certificate");
        if (certs == null || certs.length == 0) {
            throw new ForbiddenException("no client cert");
        }
        String cn = extractCn(certs[0].getSubjectX500Principal());
        if (!cn.endsWith(".internal.svc.cluster.local")) {
            throw new ForbiddenException("untrusted cn");
        }
        return syncService.run();
    }
}

